import json, math, random, sys, time
from pathlib import Path


def clear_of(start, length, windows):
    while True:
        old = start
        for a,b in windows:
            if start < b and a < start + length:
                start = b
        if start == old: return start

class Solver:
    def __init__(self, week, seed=1):
        self.w=week; self.r=random.Random(seed)
        self.presses={p['id']:p for p in week['presses']}
        self.pids=list(self.presses)
        self.jobs={j['id']:j for j in week['jobs']}
        self.jids=list(self.jobs)
        self.eligible={jid:[pid for pid,p in self.presses.items() if self.jobs[jid]['tonnage']<=p['tonnage']] for jid in self.jids}
        self.runtime={(jid,pid):-(-self.jobs[jid]['strokes']//self.presses[pid]['strokes_per_minute']) for jid in self.jids for pid in self.eligible[jid]}
        self.setup=week['setup_minutes']; self.sc=week['setup_cost_per_minute']

    def pcost(self,pid,seq, details=False):
        p=self.presses[pid]; clock=0; fam=p['initial_family']; val=0; out=[]
        for jid in seq:
            j=self.jobs[jid]; change=self.setup[fam][j['family']]
            cs=clear_of(clock,change,p['maintenance'])
            run=self.runtime[jid,pid]
            st=clear_of(max(cs+change,j['release']),run,p['maintenance']); end=st+run
            tard=max(0,end-j['due']); val += self.sc*change+j['weight']*tard
            if details: out.append((jid,cs,st,end,tard,change))
            clock=end; fam=j['family']
        return (val,out) if details else val

    def total(self,s): return sum(self.pcost(pid,s[pid]) for pid in self.pids)

    def dispatch(self, noise=0, family_bias=0, random_ties=False):
        state={pid:(0,self.presses[pid]['initial_family']) for pid in self.pids}; s={pid:[] for pid in self.pids}
        jobs=sorted(self.jobs.values(), key=lambda j:(j['due']+self.r.uniform(-noise,noise),j['id']))
        for j in jobs:
            cand=[]
            for pid in self.eligible[j['id']]:
                p=self.presses[pid]; clock,fam=state[pid]; ch=self.setup[fam][j['family']]
                cs=clear_of(clock,ch,p['maintenance']); run=self.runtime[j['id'],pid]
                st=clear_of(max(cs+ch,j['release']),run,p['maintenance']); end=st+run
                score=end + family_bias*ch + (self.r.random()*1e-3 if random_ties else 0)
                cand.append((score,end,pid))
            _,end,pid=min(cand)
            s[pid].append(j['id']); state[pid]=(end,j['family'])
        return s

    def family_construct(self):
        # Assign jobs greedily in family/due batches, trying all insertion locations.
        s={pid:[] for pid in self.pids}; costs={pid:0 for pid in self.pids}
        order=sorted(self.jids,key=lambda x:(self.jobs[x]['due'], -self.jobs[x]['weight']))
        # Insert EDD jobs at their best current position, allowing batching around existing families.
        for jid in order:
            best=None
            for pid in self.eligible[jid]:
                seq=s[pid]
                for k in range(len(seq)+1):
                    nv=self.pcost(pid,seq[:k]+[jid]+seq[k:])
                    delta=nv-costs[pid]
                    key=(delta,nv,self.r.random())
                    if best is None or key<best[0]: best=(key,pid,k,nv)
            _,pid,k,nv=best; s[pid].insert(k,jid); costs[pid]=nv
        return s

    def descent_relocate(self,s, deadline, shuffled=True):
        costs={pid:self.pcost(pid,s[pid]) for pid in self.pids}; total=sum(costs.values()); improved=True
        while improved and time.time()<deadline:
            improved=False; order=self.jids[:]
            if shuffled:self.r.shuffle(order)
            else: order.sort(key=lambda j:(-self.jobs[j]['weight'],self.jobs[j]['due']))
            loc={jid:(pid,i) for pid in self.pids for i,jid in enumerate(s[pid])}
            for jid in order:
                if time.time()>=deadline: break
                ap,ai=loc[jid]; olda=s[ap]; removed=olda[:ai]+olda[ai+1:]; ca=self.pcost(ap,removed)
                best_delta=0; best=None
                for bp in self.eligible[jid]:
                    base=removed if bp==ap else s[bp]
                    oldcost=costs[ap] if bp==ap else costs[ap]+costs[bp]
                    for bi in range(len(base)+1):
                        if bp==ap and bi==ai: continue
                        newb=base[:bi]+[jid]+base[bi:]
                        nc=self.pcost(bp,newb)
                        newcost=nc if bp==ap else ca+nc
                        delta=newcost-oldcost
                        if delta<best_delta:
                            best_delta=delta; best=(bp,bi,removed,newb,ca,nc)
                if best:
                    bp,bi,removed,newb,ca,nc=best
                    if bp==ap:
                        s[ap]=newb; costs[ap]=nc
                    else:
                        s[ap]=removed; s[bp]=newb; costs[ap]=ca; costs[bp]=nc
                    total += best_delta; improved=True
                    loc={x:(p,i) for p in self.pids for i,x in enumerate(s[p])}
        return total

    def anneal(self,s,seconds,best_global=None):
        deadline=time.time()+seconds
        costs={pid:self.pcost(pid,s[pid]) for pid in self.pids}; cur=sum(costs.values())
        best=cur; bs={p:v[:] for p,v in s.items()}; it=0; accepted=0
        # reheat cycles, broad early temperatures suited to setup deltas (~thousands)
        while time.time()<deadline:
            frac=((time.time()-(deadline-seconds))/seconds)%1
            temp=3000*(0.02**frac)+20
            it+=1
            if self.r.random()<0.82:
                ap=self.r.choice([p for p in self.pids if s[p]])
                ai=self.r.randrange(len(s[ap])); jid=s[ap][ai]
                bp=self.r.choice(self.eligible[jid])
                removed=s[ap][:ai]+s[ap][ai+1:]
                base=removed if bp==ap else s[bp]
                bi=self.r.randrange(len(base)+1)
                # favor positions around same family and due neighbors some of the time
                if self.r.random()<0.45:
                    candidates=[k for k in range(len(base)+1) if (k>0 and self.jobs[base[k-1]]['family']==self.jobs[jid]['family']) or (k<len(base) and self.jobs[base[k]]['family']==self.jobs[jid]['family'])]
                    if candidates: bi=self.r.choice(candidates)
                newb=base[:bi]+[jid]+base[bi:]
                if bp==ap:
                    nc=self.pcost(ap,newb); delta=nc-costs[ap]
                    if delta<=0 or self.r.random()<math.exp(-delta/temp):
                        s[ap]=newb; costs[ap]=nc; cur+=delta; accepted+=1
                else:
                    ca=self.pcost(ap,removed); cb=self.pcost(bp,newb); delta=ca+cb-costs[ap]-costs[bp]
                    if delta<=0 or self.r.random()<math.exp(-delta/temp):
                        s[ap]=removed;s[bp]=newb;costs[ap]=ca;costs[bp]=cb;cur+=delta;accepted+=1
            else:
                # swap two jobs when mutually eligible
                ap,bp=self.r.sample(self.pids,2)
                if not s[ap] or not s[bp]: continue
                ai=self.r.randrange(len(s[ap])); bi=self.r.randrange(len(s[bp])); ja=s[ap][ai]; jb=s[bp][bi]
                if bp not in self.eligible[ja] or ap not in self.eligible[jb]: continue
                na=s[ap][:];nb=s[bp][:];na[ai]=jb;nb[bi]=ja
                ca=self.pcost(ap,na);cb=self.pcost(bp,nb);delta=ca+cb-costs[ap]-costs[bp]
                if delta<=0 or self.r.random()<math.exp(-delta/temp):
                    s[ap]=na;s[bp]=nb;costs[ap]=ca;costs[bp]=cb;cur+=delta;accepted+=1
            if cur<best:
                best=cur;bs={p:v[:] for p,v in s.items()}
        return best,bs,it,accepted

def main():
    path=Path(sys.argv[1]); target=int(sys.argv[2]); out=Path(sys.argv[3]); seconds=float(sys.argv[4]) if len(sys.argv)>4 else 60
    sol=Solver(json.load(open(path)),seed=int(sys.argv[5]) if len(sys.argv)>5 else 1)
    starts=[]
    starts.append(sol.dispatch())
    for noise in (50,150,300,600):
        for bias in (5,15,30): starts.append(sol.dispatch(noise,bias,True))
    starts.append(sol.family_construct())
    starts.sort(key=sol.total)
    best=sol.total(starts[0]); bs=starts[0]
    print('initial',best,[sol.total(x) for x in starts[:6]],flush=True)
    deadline=time.time()+seconds
    roundno=0
    while time.time()<deadline and best>target:
        base={p:v[:] for p,v in (starts[roundno%min(6,len(starts))] if roundno<min(6,len(starts)) else bs).items()}
        slice_sec=min(max(2,seconds/12),deadline-time.time())
        v,x,it,acc=sol.anneal(base,slice_sec)
        # short exact relocate descent
        v=sol.descent_relocate(x,min(deadline,time.time()+max(1,seconds/20)))
        if v<best:
            best=v;bs={p:q[:] for p,q in x.items()}
            print('best',best,'round',roundno,'iters',it,flush=True)
            out.parent.mkdir(exist_ok=True)
            json.dump({'presses':bs},open(out,'w'),indent=1)
        roundno+=1
    if not out.exists() or sol.total(bs)<=best:
        json.dump({'presses':bs},open(out,'w'),indent=1)
    print('final',best,'target',target,flush=True)

if __name__=='__main__': main()
