def runs(sol, seq):
    out=[]; a=0
    while a<len(seq):
        f=sol.jobs[seq[a]]['family']; b=a+1
        while b<len(seq) and sol.jobs[seq[b]]['family']==f: b+=1
        out.append((a,b))
        a=b
    return out

